=========== CtrlUnit.v ===========
     1	`timescale 1ns / 1ps
     2	`include "CtrlDefine.vh"
     3	
     4	module CtrlUnit(
     5	    input[31:0] inst,
     6	    
     7	    // FU
     8	    output  ALU_use, MEM_use, MUL_use, DIV_use, JUMP_use,
     9	       
    10	    // oprands
    11	    output [4:0] rs1_ctrl, rs2_ctrl, dst_ctrl,
    12	    output ALU_use_PC,
    13	    output ALU_use_imm,
    14	    output[2:0] ImmSel,
    15	    
    16	    // ops
    17	    output [4:0] op
    18	);
    19	   
    20	    wire[6:0] funct7 = inst[31:25];
    21	    wire[2:0] funct3 = inst[14:12];
    22	    wire[6:0] opcode = inst[6:0];
    23	    wire[4:0] rd = inst[11:7];
    24	    wire[4:0] rs1 = inst[19:15];
    25	    wire[4:0] rs2 = inst[24:20];
    26	
    27	    wire Rop = opcode == 7'b0110011;
    28	    wire Iop = opcode == 7'b0010011;
    29	    wire Bop = opcode == 7'b1100011;
    30	    wire Lop = opcode == 7'b0000011;
    31	    wire Sop = opcode == 7'b0100011;
    32	
    33	    wire funct7_0  = funct7 == 7'h0;
    34	    wire funct7_1  = funct7 == 7'h1;
    35	    wire funct7_32 = funct7 == 7'h20;
    36	
    37	    wire funct3_0 = funct3 == 3'h0;
    38	    wire funct3_1 = funct3 == 3'h1;
    39	    wire funct3_2 = funct3 == 3'h2;
    40	    wire funct3_3 = funct3 == 3'h3;
    41	    wire funct3_4 = funct3 == 3'h4;
    42	    wire funct3_5 = funct3 == 3'h5;
    43	    wire funct3_6 = funct3 == 3'h6;
    44	    wire funct3_7 = funct3 == 3'h7;
    45	
    46	    wire ADD  = Rop & funct3_0 & funct7_0;
    47	    wire SUB  = Rop & funct3_0 & funct7_32;
    48	    wire SLL  = Rop & funct3_1 & funct7_0;
    49	    wire SLT  = Rop & funct3_2 & funct7_0;
    50	    wire SLTU = Rop & funct3_3 & funct7_0;
    51	    wire XOR  = Rop & funct3_4 & funct7_0;
    52	    wire SRL  = Rop & funct3_5 & funct7_0;
    53	    wire SRA  = Rop & funct3_5 & funct7_32;
    54	    wire OR   = Rop & funct3_6 & funct7_0;
    55	    wire AND  = Rop & funct3_7 & funct7_0;
    56	
    57	    wire MUL    = Rop & funct3_0 & funct7_1;
    58	    wire MULH   = Rop & funct3_1 & funct7_1;
    59	    wire MULHSU = Rop & funct3_2 & funct7_1;
    60	    wire MULHU  = Rop & funct3_3 & funct7_1;
    61	    wire DIV    = Rop & funct3_4 & funct7_1;
    62	    wire DIVU   = Rop & funct3_5 & funct7_1;
    63	    wire REM    = Rop & funct3_6 & funct7_1;
    64	    wire REMU    = Rop & funct3_7 & funct7_1;
    65	
    66	    wire ADDI  = Iop & funct3_0;	
    67	    wire SLTI  = Iop & funct3_2;
    68	    wire SLTIU = Iop & funct3_3;
    69	    wire XORI  = Iop & funct3_4;
    70	    wire ORI   = Iop & funct3_6;
    71	    wire ANDI  = Iop & funct3_7;
    72	    wire SLLI  = Iop & funct3_1 & funct7_0;
    73	    wire SRLI  = Iop & funct3_5 & funct7_0;
    74	    wire SRAI  = Iop & funct3_5 & funct7_32;
    75	
    76	    wire BEQ = Bop & funct3_0;
    77	    wire BNE = Bop & funct3_1;
    78	    wire BLT = Bop & funct3_4;
    79	    wire BGE = Bop & funct3_5;
    80	    wire BLTU = Bop & funct3_6;
    81	    wire BGEU = Bop & funct3_7;
    82	
    83	    wire LB =  Lop & funct3_0;
    84	    wire LH =  Lop & funct3_1;
    85	    wire LW =  Lop & funct3_2;
    86	    wire LBU = Lop & funct3_4;
    87	    wire LHU = Lop & funct3_5;
    88	
    89	    wire SB = Sop & funct3_0;
    90	    wire SH = Sop & funct3_1;
    91	    wire SW = Sop & funct3_2;
    92	
    93	    wire LUI   = opcode == 7'b0110111;
    94	    wire AUIPC = opcode == 7'b0010111;
    95	
    96	    wire JAL  =  opcode == 7'b1101111;
    97	    wire JALR = (opcode == 7'b1100111) && funct3_0;
    98	
    99	    wire R_valid = AND | OR | ADD | XOR | SLL | SRL | SRA | SUB | SLT | SLTU 
   100	        | MUL | MULH | MULHSU | MULHU | DIV | DIVU | REM | REMU;
   101	    wire I_valid = ANDI | ORI | ADDI | XORI | SLLI | SRLI | SRAI | SLTI | SLTIU;
   102	    wire B_valid = BEQ | BNE | BLT | BGE | BLTU | BGEU;
   103	    wire L_valid = LW | LH | LB | LHU | LBU;
   104	    wire S_valid = SW | SH | SB;
   105	
   106	    wire use_ALU = AND | OR | ADD | XOR | SLL | SRL | SRA | SUB | SLT | SLTU
   107	        | I_valid | LUI | AUIPC;
   108	    wire use_MEM = L_valid | S_valid;
   109	    wire use_MUL = MUL | MULH | MULHSU | MULHU;
   110	    wire use_DIV = DIV | DIVU | REM | REMU;
   111	    wire use_JUMP = B_valid | JAL | JALR;
   112	
   113	    // TODO: implement — generate control signals and operation encoding
   114	    assign ALU_use = 0;
   115	    assign MEM_use = 0;
   116	    assign MUL_use = 0;
   117	    assign DIV_use = 0;
   118	    assign JUMP_use = 0;
   119	    assign op = 5'b0;
   120	    assign dst_ctrl = 5'b0;
   121	    assign rs1_ctrl = 5'b0;
   122	    assign rs2_ctrl = 5'b0;
   123	    assign ALU_use_PC = 0;
   124	    assign ALU_use_imm = 0;
   125	    assign ImmSel = 3'b0;
   126	
   127	endmodule=========== FU_ALU.v ===========
     1	`timescale 1ns / 1ps
     2	
     3	module FU_ALU(
     4	    input clk, EN,
     5	    input[3:0] ALUControl,
     6	    input[31:0] ALUA, ALUB,
     7	    output[31:0] res,
     8	    output zero, overflow,
     9	    output finish
    10	);
    11	
    12	    reg state;
    13	    assign finish = state == 1'b1;
    14	    initial begin
    15	        state = 0;
    16	    end
    17	
    18	    localparam ALU_ADD  = 4'b0001;
    19	    localparam ALU_SUB  = 4'b0010;
    20	    localparam ALU_AND  = 4'b0011;
    21	    localparam ALU_OR   = 4'b0100;
    22	    localparam ALU_XOR  = 4'b0101;
    23	    localparam ALU_SLL  = 4'b0110;
    24	    localparam ALU_SRL  = 4'b0111;
    25	    localparam ALU_SLT  = 4'b1000;
    26	    localparam ALU_SLTU = 4'b1001;
    27	    localparam ALU_SRA  = 4'b1010;
    28	    localparam ALU_Ap4  = 4'b1011;
    29	    localparam ALU_Bout = 4'b1100;
    30	
    31	    // TODO: implement — stateful ALU functional unit
    32	    // On EN & ~state: latch inputs (ALUA, ALUB, ALUControl) and set state to 1
    33	    // On state == 1: reset state to 0
    34	    // Must support: ADD, SUB, AND, OR, XOR, SLL, SRL, SLT, SLTU, SRA, A+4, B-passthrough
    35	    // zero should be 1 when res is all zeros.
    36	    // overflow should be set for signed ADD/SUB overflow.
    37	    assign res = 32'b0;
    38	    assign zero = 1'b0;
    39	    assign overflow = 1'b0;
    40	
    41	endmodule=========== FU_div.v ===========
     1	`timescale 1ns / 1ps
     2	
     3	module FU_div(
     4	    input clk, EN,
     5	    input[31:0] A, B,
     6	    output[31:0] res,
     7	    output finish
     8	);
     9	
    10	    wire res_valid;
    11	    wire[63:0] divres;
    12	    
    13	    reg state;
    14	    assign finish = res_valid & state;
    15	    initial begin
    16	        state = 0;
    17	    end
    18	
    19	    reg A_valid, B_valid;
    20	    reg[31:0] A_reg, B_reg;
    21	
    22	    // TODO: implement — division functional unit
    23	    // On EN & ~state: latch inputs (A, B), set A_valid and B_valid to 1, set state to 1.
    24	    // When res_valid: clear A_valid, B_valid, state to 0.
    25	    // Otherwise: clear A_valid, B_valid but keep state.
    26	    // Instantiate divider IP with AXI-style valid/data interface.
    27	    // Result is the quotient from divres[63:32].
    28	    assign res = 32'b0;
    29	
    30	endmodule=========== FU_jump.v ===========
     1	`timescale 1ns / 1ps
     2	
     3	module FU_jump(
     4		input clk, EN, JALR,
     5		input[3:0] cmp_ctrl,
     6		input[31:0] rs1_data, rs2_data, imm, PC,
     7		output[31:0] PC_jump, PC_wb,
     8		output is_jump, finish
     9	);
    10	
    11		wire cmp_res;
    12	    reg state;
    13	    assign finish = state == 1'b1;
    14		initial begin
    15	        state = 0;
    16	    end
    17	
    18		reg JALR_reg;
    19		reg[3:0] cmp_ctrl_reg = 0;
    20		reg[31:0] rs1_data_reg = 0, rs2_data_reg = 0, imm_reg = 0, PC_reg = 0;
    21	
    22	    // TODO: implement — jump/branch functional unit
    23	    // On EN & ~state: latch inputs (JALR, cmp_ctrl, rs1_data, rs2_data, imm, PC) and set state to 1.
    24	    // On state==1: reset state to 0.
    25	    // Use cmp_32 to compare rs1_data_reg and rs2_data_reg.
    26	    // Compute PC_jump = (JALR ? rs1_data_reg : PC_reg) + imm_reg.
    27	    // Compute PC_wb = PC_reg + 4.
    28	    // is_jump = cmp_ctrl_reg[0] | cmp_res (unconditional or condition met).
    29	    assign is_jump = 1'b0;
    30	    assign PC_jump = 32'b0;
    31	    assign PC_wb = 32'b0;
    32	
    33	endmodule=========== FU_mem.v ===========
     1	`timescale 1ns / 1ps
     2	
     3	module FU_mem(
     4	    input clk, EN, mem_w,
     5	    input[2:0] bhw,
     6	    input[31:0] rs1_data, rs2_data, imm,
     7	    output[31:0] mem_data,
     8	    output finish
     9	);
    10	
    11	    reg[1:0] state;
    12	    assign finish = state[0] == 1'b1;
    13	    initial begin
    14	        state = 0;
    15	    end
    16	
    17	    reg mem_w_reg;
    18	    reg[2:0] bhw_reg;
    19	    reg[31:0] rs1_data_reg, rs2_data_reg, imm_reg;
    20	
    21	    // TODO: implement — memory functional unit
    22	    // On EN & ~|state: latch inputs (mem_w, bhw, rs1_data, rs2_data, imm) and set state to 2'b10.
    23	    // State shifts right each cycle (2'b10 -> 2'b01 -> 2'b00).
    24	    // finish when state[0] == 1.
    25	    // Compute address = rs1_data_reg + imm_reg using add_32.
    26	    // Instantiate RAM_B with computed address.
    27	    assign mem_data = 32'b0;
    28	
    29	endmodule=========== FU_mul.v ===========
     1	`timescale 1ns / 1ps
     2	
     3	module FU_mul(
     4	    input clk, EN,
     5	    input[31:0] A, B,
     6	    output[31:0] res,
     7	    output finish
     8	);
     9	
    10	    reg[6:0] state;
    11	    assign finish = state[0] == 1'b1;
    12	    initial begin
    13	        state = 0;
    14	    end
    15	
    16	    // TODO: implement — multiplication functional unit
    17	    // On EN & ~|state: latch inputs (A, B) and set state to 7'b100_0000.
    18	    // State shifts right each cycle (64-cycle latency).
    19	    // finish when state[0] == 1.
    20	    // Instantiate multiplier IP and use lower 32 bits of result.
    21	    assign res = 32'b0;
    22	
    23	endmodule=========== ImmGen.v ===========
