    14	    wire I = ImmSel == Imm_type_I;
    15	    wire B = ImmSel == Imm_type_B;
    16	    wire J = ImmSel == Imm_type_J;
    17	    wire S = ImmSel == Imm_type_S;
    18	    wire U = ImmSel == Imm_type_U;
    19	
    20	    // TODO: implement — generate sign-extended immediates for I, B, J, S, U types
    21	    assign Imm_out = 32'b0;
