    23	    // TODO: implement — byte/halfword/word write logic
    24	    // On negedge clka, if wea & addra != SIM_UART_ADDR:
    25	    //   Always write dina[7:0] to data[addra].
    26	    //   If halfword or word (mem_u_b_h_w[0] | mem_u_b_h_w[1]), also write dina[15:8].
