    22	module    REG_IF_IS(input clk,                                      //IF/ID Latch
    23	                    input rst,
    24	                    input EN,                                       //流水寄存器使能
    25	                    input flush,                                    //控制竞争清除并等待
    26	                    input [31:0] PCOUT,                             //指令存储器指针
    27	                    input [31:0] IR,                                //指令存储器输出
    28	
    29	                    output reg[31:0] IR_IS,                         //取指锁存
    30	                    output reg[31:0] PCurrent_IS                    //当前存在指令地址
    31	                );
    32	
    33	//reg[31:0]PCurrent_ID,IR_ID;
    34	    always @(posedge clk or posedge rst) begin
    35	        if(rst) begin
    36	             IR_IS <= 32'h00000000;                            //复位清零s
    37	             PCurrent_IS <= 32'h00000000;                     //复位清零
    38	            end
    39	        else if(EN)begin
    40	            if(flush)begin
    41	                IR_IS <= 32'h00000000;              //IR waiting for Control Hazards i清s除指令并暂停
    42	            end
    43	            else begin
    44	                IR_IS <= IR;                       //正常取指,传送下一流水级译码
    45	                PCurrent_IS <= PCOUT;  end         //当前取指PC地址，Branch/Junp指令计算目标地址用(非PC+4)
    46	            end
    47	    end
